14	
15	export const REASONS = {
16	  journal:
17	    'Blocked by the harness guard: raw journal in window. ' +
18	    'Use `npm run agent:log` — the summary, not .agent-log/ itself.',
19	  'no-verify':
20	    'Blocked by the harness guard: this skips the git hooks. ' +
21	    'Fix what the pre-commit hook reports. Only the human may skip it, in a terminal.',
22	};
