63	  if (!payload || typeof payload !== 'object') return [];
64	  const input = payload.tool_input ?? payload;
65	  if (payload.tool_name && EDITOR_TOOLS.has(payload.tool_name)) {
66	    return EDITOR_ACTION_FIELDS.flatMap((k) => (typeof input[k] === 'string' ? [input[k]] : []));
67	  }
