import { encode } from 'z85';

const MONTHS = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'] as const;
const TWO_DIGITS = 2;
const CENTURY = 100;

/**
 * Coupon codes of test-cases/README.md: the Z85 encoding of `<MMM><YY>-<NN>`.
 * The server checks the month in its local time, and the tests run on the same machine,
 * so the month comes from the local time of this machine.
 */
export class CouponHelper {
  static currentMonthCode(discountPercent: number, now: Date = new Date()): string {
    return CouponHelper.codeFor(now, discountPercent);
  }

  static previousMonthCode(discountPercent: number, now: Date = new Date()): string {
    const previousMonth = new Date(now.getFullYear(), now.getMonth() - 1, 1);
    return CouponHelper.codeFor(previousMonth, discountPercent);
  }

  private static codeFor(month: Date, discountPercent: number): string {
    const year = String(month.getFullYear() % CENTURY).padStart(TWO_DIGITS, '0');
    const discount = String(discountPercent).padStart(TWO_DIGITS, '0');
    const code = encode(`${MONTHS[month.getMonth()]}${year}-${discount}`);
    if (!code) throw new Error(`Cannot encode the coupon text for ${month.toDateString()}`);
    return code;
  }
}

