import { expect, type APIRequestContext, type APIResponse } from '@playwright/test';

type HttpMethod = 'GET' | 'POST' | 'PUT';

interface RequestOptions {
  token?: string;
  data?: unknown;
  params?: Record<string, string>;
}

/** Base for the API clients: sends a request, checks that it succeeded and returns the JSON body. */
export abstract class ApiClient {
  constructor(protected readonly request: APIRequestContext) {}

  protected async send<T = unknown>(method: HttpMethod, path: string, options: RequestOptions = {}): Promise<T> {
    const response: APIResponse = await this.request.fetch(path, {
      method,
      data: options.data,
      params: options.params,
      headers: options.token ? { Authorization: `Bearer ${options.token}` } : undefined,
    });
    await expect(response, `${method} ${path} succeeds: ${await response.text()}`).toBeOK();
    return (await response.json()) as T;
  }
}

