        fullName: address.name,
        mobileNum: Number(address.mobileNumber),
        zipCode: address.zipCode,
        streetAddress: address.streetAddress,
        city: address.city,
        state: address.state,
      },
    });
  }

  async addCard(customer: Customer, card: SavedCard): Promise<number> {
    const body = await this.send<CreatedResponse>('POST', API_ROUTES.cards, {
      token: customer.token,
      data: {
        fullName: card.name,
        cardNum: Number(card.cardNumber),
        expMonth: card.expiryMonth,
        expYear: card.expiryYear,
      },
    });
    return body.data.id;
  }

  /** Adds money to the wallet. The shop takes it from a saved card. */
  async addWalletMoney(customer: Customer, amount: number, cardId: number): Promise<void> {
    await this.send('PUT', API_ROUTES.walletBalance, {
      token: customer.token,
      data: { balance: amount, paymentId: cardId },
    });
  }
}

