import type { Locator, Page } from '@playwright/test';
import { expectHidden, expectText, expectTextHolds, expectVisible } from '@/utils/assertions/ui-assertions';

/** The top bar: the account menu and the basket button with its counter. */
export class NavbarComponent {
  private readonly accountButton: Locator;
  private readonly basketButton: Locator;
  private readonly basketCounter: Locator;
  private readonly accountMenu: Locator;

  constructor(private readonly page: Page) {
    this.accountButton = page.locator('#navbarAccount');
    this.basketButton = page.getByRole('button', { name: 'Show the shopping cart' });
    this.basketCounter = this.basketButton.locator('.mdc-button__label > span').last();
    this.accountMenu = page.getByRole('menu').first();
  }

  async openAccountMenu(): Promise<void> {
    await this.accountButton.click();
    await expectVisible(this.accountMenu, 'Account menu');
  }

  async closeAccountMenu(): Promise<void> {
    await this.page.keyboard.press('Escape');
    await expectHidden(this.accountMenu, 'Account menu');
  }

  async clickYourBasket(): Promise<void> {
    await this.basketButton.click();
  }

  async openOrderHistory(): Promise<void> {
    await this.openOrdersAndPaymentItem('Go to order history page');
  }

  async openDigitalWallet(): Promise<void> {
    await this.openOrdersAndPaymentItem('Go to wallet page');
  }

  async shouldSeeAccountMenuItem(itemText: string): Promise<void> {
    await expectVisible(this.accountMenu.getByRole('menuitem', { name: itemText }), `Account menu item "${itemText}"`);
  }

  async shouldNotSeeInAccountMenu(text: string): Promise<void> {
    await expectHidden(this.accountMenu.getByText(text), `"${text}" in the account menu`);
  }

  async shouldSeeEmailInAccountMenu(email: string): Promise<void> {
    await expectVisible(this.accountMenu.getByRole('menuitem').filter({ hasText: email }), `Email ${email} in the account menu`);
  }

  async shouldSeeBasketCounter(count: number): Promise<void> {
    await expectText(this.basketCounter, String(count), 'Basket counter');
  }

  /** The counter shows the value and does not change it for a while. */
  async shouldKeepBasketCounter(count: number): Promise<void> {
    await expectTextHolds(this.basketCounter, String(count), 'Basket counter');
  }

  private async openOrdersAndPaymentItem(itemLabel: string): Promise<void> {
    await this.openAccountMenu();
    await this.page.getByRole('menuitem', { name: 'Show Orders and Payment Menu' }).click();
    await this.page.getByRole('menuitem', { name: itemLabel }).click();
  }
}

