import type { Locator, Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import {
  expectCount,
  expectDisabled,
  expectHidden,
  expectText,
  expectTextHolds,
  expectUrl,
} from '@/utils/assertions/ui-assertions';
import { UI_ROUTE_PATTERNS, UI_ROUTES } from '@/utils/constants/routes';
import type { BasketLine, Product } from '@/utils/types/shop';

const TOTAL_PRICE_PREFIX = 'Total Price: ';

/** The basket page `/#/basket`. */
export class BasketPage extends BasePage {
  private readonly title: Locator;
  private readonly rows: Locator;
  private readonly totalPrice: Locator;
  private readonly checkoutButton: Locator;

  constructor(page: Page) {
    super(page);
    const root = page.locator('app-basket');
    this.title = root.getByRole('heading', { level: 1 });
    this.rows = root.locator('mat-row');
    this.totalPrice = root.locator('#price');
    this.checkoutButton = root.locator('#checkoutButton');
  }

  async open(): Promise<void> {
    await this.page.goto(UI_ROUTES.basket);
    await this.shouldSeePage();
  }

  async clickCheckout(): Promise<void> {
    await this.checkoutButton.click();
  }

  async clickIncreaseQuantity(product: Product): Promise<void> {
    await this.quantityButtons(product).last().click();
  }

  async clickDecreaseQuantity(product: Product): Promise<void> {
    await this.quantityButtons(product).first().click();
  }

  /** Clicks the plus button once for each missing item, and waits for each new quantity. */
  async increaseQuantityTo(product: Product, quantity: number): Promise<void> {
    const current = Number((await this.quantity(product).innerText()).trim());
    for (let next = current + 1; next <= quantity; next += 1) {
      await this.clickIncreaseQuantity(product);
      await this.shouldSeeQuantity(product, next);
    }
  }

  async clickRemove(product: Product): Promise<void> {
    await this.row(product).locator('mat-cell.mat-column-remove button').click();
  }

  async shouldSeePage(): Promise<void> {
    await expectUrl(this.page, UI_ROUTE_PATTERNS.basket, 'Basket page');
    await expectText(this.title, /Your Basket/, 'Basket title');
  }

  async shouldSeeRowCount(count: number): Promise<void> {
    await expectCount(this.rows, count, 'Basket rows');
  }

  async shouldSeeLine(line: BasketLine): Promise<void> {
    const { product, quantity } = line;
    await expectCount(this.row(product), 1, `Basket row of ${product.name}`);
    await this.shouldSeeQuantity(product, quantity);
    await expectText(this.row(product).locator('mat-cell.mat-column-price'), product.price, `Price of ${product.name}`);
  }

  async shouldSeeQuantity(product: Product, quantity: number): Promise<void> {
    await expectText(this.quantity(product), String(quantity), `Quantity of ${product.name}`);
  }

  /** The quantity shows the value and does not change it for a while. */
  async shouldKeepQuantity(product: Product, quantity: number): Promise<void> {
    await expectTextHolds(this.quantity(product), String(quantity), `Quantity of ${product.name}`);
  }

  async shouldNotSeeProduct(product: Product): Promise<void> {
    await expectHidden(this.row(product), `Basket row of ${product.name}`);
  }

  async shouldSeeTotalPrice(price: string): Promise<void> {
    await expectText(this.totalPrice, `${TOTAL_PRICE_PREFIX}${price}`, 'Basket total');
  }

  /** The total shows the value and does not change it for a while. */
  async shouldKeepTotalPrice(price: string): Promise<void> {
    await expectTextHolds(this.totalPrice, `${TOTAL_PRICE_PREFIX}${price}`, 'Basket total');
  }

  async shouldSeeCheckoutDisabled(): Promise<void> {
    await expectDisabled(this.checkoutButton, 'Button Checkout');
  }

  private row(product: Product): Locator {
    return this.rows.filter({ has: this.page.locator('mat-cell.mat-column-product', { hasText: product.name }) });
  }

  private quantity(product: Product): Locator {
    return this.row(product).locator('mat-cell.mat-column-quantity > span');
  }

  private quantityButtons(product: Product): Locator {
    return this.row(product).locator('mat-cell.mat-column-quantity button');
  }
}

