import type { Page } from '@playwright/test';
import { NavbarComponent } from '@/page-objects/components/navbar.component';
import { SnackBarComponent } from '@/page-objects/components/snack-bar.component';

export abstract class BasePage {
  private readonly navbarComponent: NavbarComponent;
  private readonly snackBarComponent: SnackBarComponent;

  constructor(protected readonly page: Page) {
    this.navbarComponent = new NavbarComponent(page);
    this.snackBarComponent = new SnackBarComponent(page);
  }

  /** The top bar: account menu, basket button and basket counter. */
  get navbar(): NavbarComponent {
    return this.navbarComponent;
  }

  /** The short messages at the bottom of the page. */
  get snackBar(): SnackBarComponent {
    return this.snackBarComponent;
  }

  abstract shouldSeePage(): Promise<void>;
}

