import { UI_ROUTE_PATTERNS } from '@/utils/constants/routes';
import type { SavedAddress } from '@/utils/types/shop';

/** Checkout step 1: `Select an address`. */
export class AddressSelectPage extends BasePage {
  private readonly title: Locator;
  private readonly rows: Locator;
  private readonly continueButton: Locator;

  constructor(page: Page) {
    super(page);
    const root = page.locator('app-address-select');
    this.title = root.getByRole('heading', { level: 1 });
    this.rows = root.locator('mat-row');
    this.continueButton = root.getByRole('button', { name: 'Proceed to payment selection' });
  }

  async selectAddress(address: SavedAddress): Promise<void> {
    await this.row(address).locator('mat-radio-button').click();
  }

  async clickContinue(): Promise<void> {
    await this.continueButton.click();
  }

  async shouldSeePage(): Promise<void> {
    await expectUrl(this.page, UI_ROUTE_PATTERNS.addressSelect, 'Address selection page');
    await expectText(this.title, 'Select an address', 'Address selection title');
  }

  async shouldSeeAddress(address: SavedAddress): Promise<void> {
    const row = this.row(address);
    await expectCount(row, 1, `Saved address of ${address.name}`);
    await expectText(row.locator('mat-cell.mat-column-Name'), address.name, 'Address name');
    await expectText(
      row.locator('mat-cell.mat-column-Address'),
      `${address.streetAddress}, ${address.city}, ${address.state}, ${address.zipCode}`,
      'Address line',
    );
    await expectText(row.locator('mat-cell.mat-column-Country'), address.country, 'Address country');
  }

  private row(address: SavedAddress): Locator {
    return this.rows.filter({ hasText: address.streetAddress });
  }
}

