import type { Locator, Page } from '@playwright/test';
import { expectHidden, expectText, expectVisible } from '@/utils/assertions/ui-assertions';
import { API_ROUTE_PATTERNS } from '@/utils/constants/routes';
import { UI_MESSAGES } from '@/utils/constants/ui-messages';

/** The panel `Add a coupon` on the payment page. */
export class CouponPanelComponent {
  private readonly header: Locator;
  private readonly couponField: Locator;
  private readonly redeemButton: Locator;
  private readonly confirmation: Locator;
  private readonly error: Locator;

  constructor(private readonly page: Page) {
    const root = page.locator('#collapseCouponElement');
    this.header = root.locator('mat-expansion-panel-header');
    this.couponField = root.locator('#coupon');
    this.redeemButton = root.locator('#applyCouponButton');
    this.confirmation = root.locator('.confirmation');
    this.error = root.locator('.error');
  }

  async open(): Promise<void> {
    await this.header.click();
    await expectVisible(this.couponField, 'Field Coupon');
  }

  /** Types the code, clicks `Redeem` and waits for the answer of the server. */
  async redeemCoupon(code: string): Promise<void> {
    await this.couponField.fill(code);
    const couponResponse = this.page.waitForResponse((response) => API_ROUTE_PATTERNS.basketCoupon.test(response.url()));
    await this.redeemButton.click();
    await couponResponse;
  }

  async shouldSeePanel(): Promise<void> {
    await expectText(this.header.locator('mat-panel-title'), 'Add a coupon', 'Panel Add a coupon');
  }

  async shouldSeeDiscountConfirmation(discountPercent: number): Promise<void> {
    await expectText(this.confirmation, UI_MESSAGES.couponAccepted(discountPercent), 'Coupon confirmation');
  }

  async shouldSeeInvalidCouponError(): Promise<void> {
    await expectText(this.error, UI_MESSAGES.invalidCoupon, 'Coupon error');
  }

  async shouldNotSeeDiscountConfirmation(): Promise<void> {
    await expectHidden(this.page.getByText(UI_MESSAGES.couponAcceptedPrefix), 'Coupon confirmation');
  }
}

