import type { Locator, Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { CouponPanelComponent } from '@/page-objects/checkout/components/coupon-panel.component';
import { expectCount, expectDisabled, expectEnabled, expectText, expectUrl } from '@/utils/assertions/ui-assertions';
import { UI_ROUTE_PATTERNS } from '@/utils/constants/routes';
import type { SavedCard } from '@/utils/types/shop';

const MASKED_CARD_DIGITS = 12;
const VISIBLE_CARD_DIGITS = 4;

/** Checkout step 3: `My Payment Options`, with the wallet and the coupon panel. */
export class PaymentPage extends BasePage {
  private readonly title: Locator;
  private readonly cardRows: Locator;
  private readonly walletBalance: Locator;
  private readonly continueButton: Locator;
  private readonly couponPanel: CouponPanelComponent;

  constructor(page: Page) {
    super(page);
    const root = page.locator('app-payment');
    this.title = root.getByRole('heading', { name: 'My Payment Options' });
    this.cardRows = root.locator('app-payment-method mat-row');
    this.walletBalance = root.locator('b', { hasText: 'Wallet Balance' }).locator('.confirmation');
    this.continueButton = root.getByRole('button', { name: 'Proceed to review' });
    this.couponPanel = new CouponPanelComponent(page);
  }

  async selectCard(card: SavedCard): Promise<void> {
    await this.cardRow(card).locator('mat-radio-button').click();
  }

  async clickContinue(): Promise<void> {
    await this.continueButton.click();
  }

  async clickPayWithWallet(amount: string): Promise<void> {
    await this.walletPayButton(amount).click();
  }

  async openCouponPanel(): Promise<void> {
    await this.couponPanel.open();
  }

  async redeemCoupon(code: string): Promise<void> {
    await this.couponPanel.redeemCoupon(code);
  }

  async shouldSeePage(): Promise<void> {
    await expectUrl(this.page, UI_ROUTE_PATTERNS.payment, 'Payment page');
    await expectText(this.title, 'My Payment Options', 'Payment page title');
  }

  async shouldSeeSavedCard(card: SavedCard): Promise<void> {
    const row = this.cardRow(card);
    await expectCount(row, 1, 'Saved card');
    await expectText(row.locator('mat-cell.mat-column-Name'), card.name, 'Card holder');
    await expectText(row.locator('mat-cell.mat-column-Expiry'), `${card.expiryMonth}/${card.expiryYear}`, 'Card expiry');
  }

  async shouldSeeCouponPanel(): Promise<void> {
    await this.couponPanel.shouldSeePanel();
  }

  async shouldSeeCouponDiscountConfirmation(discountPercent: number): Promise<void> {
    await this.couponPanel.shouldSeeDiscountConfirmation(discountPercent);
  }

  async shouldSeeInvalidCouponError(): Promise<void> {
    await this.couponPanel.shouldSeeInvalidCouponError();
  }

  async shouldNotSeeCouponDiscountConfirmation(): Promise<void> {
    await this.couponPanel.shouldNotSeeDiscountConfirmation();
  }

  async shouldSeeWalletBalance(balance: string): Promise<void> {
    await expectText(this.walletBalance, balance, 'Wallet Balance');
  }

  async shouldSeeWalletPayButtonDisabled(amount: string): Promise<void> {
    await expectDisabled(this.walletPayButton(amount), `Button Pay ${amount}`);
  }

  async shouldSeeWalletPayButtonEnabled(amount: string): Promise<void> {
    await expectEnabled(this.walletPayButton(amount), `Button Pay ${amount}`);
  }

  private cardRow(card: SavedCard): Locator {
    const maskedNumber = `${'*'.repeat(MASKED_CARD_DIGITS)}${card.cardNumber.slice(-VISIBLE_CARD_DIGITS)}`;
    return this.cardRows.filter({
      has: this.page.locator('mat-cell.mat-column-Number').getByText(maskedNumber, { exact: true }),
    });
  }

  private walletPayButton(amount: string): Locator {
    return this.page.locator('app-payment').getByRole('button', { name: `Pay ${amount}`, exact: true });
  }
}

