import type { Locator, Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { expectContainText, expectText, expectUrl, expectVisible } from '@/utils/assertions/ui-assertions';
import { UI_ROUTE_PATTERNS } from '@/utils/constants/routes';
import type { OrderTotals, SavedAddress, SavedCard } from '@/utils/types/shop';

const VISIBLE_CARD_DIGITS = 4;

/** Checkout step 4: the review page with `Order Summary` and `Place your order and pay`. */
export class OrderSummaryPage extends BasePage {
  private readonly root: Locator;
  private readonly summaryTable: Locator;
  private readonly addressCard: Locator;
  private readonly paymentCard: Locator;
  private readonly placeOrderButton: Locator;

  constructor(page: Page) {
    super(page);
    this.root = page.locator('app-order-summary');
    this.summaryTable = this.root.locator('table');
    this.addressCard = this.root.locator('mat-card mat-card').filter({ hasText: 'Delivery Address' });
    this.paymentCard = this.root.locator('mat-card mat-card').filter({ hasText: 'Payment Method' });
    this.placeOrderButton = this.root.getByRole('button', { name: 'Complete your purchase' });
  }

  async clickPlaceOrderAndPay(): Promise<void> {
    await this.placeOrderButton.click();
  }

  async shouldSeePage(): Promise<void> {
    await expectUrl(this.page, UI_ROUTE_PATTERNS.orderSummary, 'Order summary page');
    await expectVisible(this.root.getByText('Order Summary', { exact: true }), 'Order Summary heading');
  }

  async shouldSeeTotals(totals: OrderTotals): Promise<void> {
    await expectText(this.totalLine('Items'), totals.items, 'Items');
    await expectText(this.totalLine('Delivery'), totals.delivery, 'Delivery');
    await expectText(this.totalLine('Promotion'), totals.promotion, 'Promotion');
    await expectText(this.totalLine('Total Price'), totals.totalPrice, 'Total Price');
  }

  async shouldSeeDeliveryAddress(address: SavedAddress): Promise<void> {
    await expectContainText(this.addressCard, address.name, 'Delivery address name');
    await expectContainText(
      this.addressCard,
      `${address.streetAddress}, ${address.city}, ${address.state}, ${address.zipCode}`,
      'Delivery address line',
    );
    await expectContainText(this.addressCard, address.country, 'Delivery address country');
  }

  async shouldSeeCardPayment(card: SavedCard): Promise<void> {
