import type { Locator, Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { expectCount, expectText, expectUrl } from '@/utils/assertions/ui-assertions';
import { UI_ROUTE_PATTERNS } from '@/utils/constants/routes';
import { UI_MESSAGES } from '@/utils/constants/ui-messages';
import type { BasketLine, OrderTotals } from '@/utils/types/shop';

const TOTAL_LABELS = ['Items', 'Delivery', 'Promotion', 'Total Price'];

/** The confirmation page `/#/order-completion/<order ID>`. */
export class OrderCompletionPage extends BasePage {
  private readonly heading: Locator;
  private readonly productRows: Locator;
  private readonly totalLabels: Locator;
  private readonly totalValues: Locator;

  constructor(page: Page) {
    super(page);
    const root = page.locator('app-order-completion');
    this.heading = root.locator('h1');
    this.productRows = root.locator('mat-row');
    this.totalLabels = root.locator('mat-footer-cell.mat-column-quantity tr');
    this.totalValues = root.locator('mat-footer-cell.mat-column-total-price tr');
  }

  /** The order ID from the page URL. */
  async readOrderId(): Promise<string> {
    await this.shouldSeePage();
    const orderId = UI_ROUTE_PATTERNS.orderCompletion.exec(this.page.url())?.[1];
    if (!orderId) throw new Error(`No order ID in the URL ${this.page.url()}`);
    return orderId;
  }

  async shouldSeePage(): Promise<void> {
    await expectUrl(this.page, UI_ROUTE_PATTERNS.orderCompletion, 'Order confirmation page');
  }

  async shouldSeeThankYou(): Promise<void> {
    await expectText(this.heading, UI_MESSAGES.orderThankYou, 'Confirmation heading');
  }

  async shouldSeeProductLine(line: BasketLine): Promise<void> {
    const row = this.productRows.filter({
      has: this.page.locator('mat-cell.mat-column-product', { hasText: line.product.name }),
    });
    await expectCount(row, 1, `Order line of ${line.product.name}`);
    await expectText(row.locator('mat-cell.mat-column-quantity'), String(line.quantity), `Quantity of ${line.product.name}`);
  }

  async shouldSeeTotals(totals: OrderTotals): Promise<void> {
    await expectText(this.totalLabels, TOTAL_LABELS, 'Order summary labels');
    await expectText(
      this.totalValues,
      [totals.items, totals.delivery, totals.promotion, totals.totalPrice],
      'Order summary values: Items, Delivery, Promotion, Total Price',
    );
  }
}

