/**
 * Test-data setup for a customer through the API: a new account, a basket, the saved address
 * and card of test-cases/README.md, and money in the wallet.
 */
import { randomUUID } from 'node:crypto';
import type { JuiceShopApi } from '@/core/api/juice-shop-api';
import { SAVED_ADDRESS, SAVED_CARD } from '@/utils/constants/shop-data';
import type { Customer } from '@/utils/types/customer';
import type { BasketLine } from '@/utils/types/shop';

const EMAIL_DOMAIN = 'example.test';
const UNIQUE_PART_LENGTH = 8;

export interface CustomerSetup {
  basket?: BasketLine[];
  withSavedAddressAndCard?: boolean;
  /** Money to add to the wallet. Needs the saved card. */
  walletBalance?: number;
}

/** Registers a new normal customer with a unique email and logs it in through the API. */
export async function createCustomer(api: JuiceShopApi): Promise<Customer> {
  const unique = `${Date.now()}-${randomUUID().slice(0, UNIQUE_PART_LENGTH)}`;
  const credentials = { email: `customer-${unique}@${EMAIL_DOMAIN}`, password: `Pw-${unique}!` };
  await api.users.register(credentials);
  return api.users.login(credentials);
}

export async function fillBasket(api: JuiceShopApi, customer: Customer, lines: BasketLine[]): Promise<void> {
  for (const line of lines) {
    const productId = await api.products.findIdByName(line.product.name);
    await api.basket.addItem(customer, productId, line.quantity);
  }
}

/** Saves the address and the card of test-cases/README.md. Returns the customer with the card id. */
export async function addSavedAddressAndCard(api: JuiceShopApi, customer: Customer): Promise<Customer> {
  await api.paymentData.addAddress(customer, SAVED_ADDRESS);
  const savedCardId = await api.paymentData.addCard(customer, SAVED_CARD);
  return { ...customer, savedCardId };
}

/** Adds money to the wallet with the saved card of the customer. */
export async function addWalletMoney(api: JuiceShopApi, customer: Customer, amount: number): Promise<void> {
  if (customer.savedCardId === undefined) {
    throw new Error('The wallet top-up needs a saved card. Save the card first.');
  }
  await api.paymentData.addWalletMoney(customer, amount, customer.savedCardId);
}

/** Creates a new customer and prepares the data that the setup asks for. */
export async function createPreparedCustomer(api: JuiceShopApi, setup: CustomerSetup): Promise<Customer> {
  let customer = await createCustomer(api);
  if (setup.withSavedAddressAndCard) customer = await addSavedAddressAndCard(api, customer);
  if (setup.basket?.length) await fillBasket(api, customer, setup.basket);
  if (setup.walletBalance) await addWalletMoney(api, customer, setup.walletBalance);
  return customer;
}

