import { test } from '@/fixtures/customer.fixture';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import {
  COUPON_DISCOUNT_PERCENT,
  DELIVERY_METHODS,
  PRODUCTS,
  SAVED_ADDRESS,
  SAVED_CARD,
} from '@/utils/constants/shop-data';
import { CouponHelper } from '@/utils/helpers/coupon-helper';

const PRODUCT_A_LINE = { product: PRODUCTS.eggfruitJuice, quantity: 2 };
const PRODUCT_B_LINE = { product: PRODUCTS.carrotJuice, quantity: 1 };
const BASKET_TOTAL = '20.97¤';
const EXPECTED_TOTALS = {
  items: '20.97¤',
  delivery: '0.99¤',
  promotion: '2.10¤',
  totalPrice: '19.86¤',
};

test.use({ customerSetup: { withSavedAddressAndCard: true } });

test('Order with a card, from the basket to the order history', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.checkout],
  annotation: { type: 'test-case', description: 'TC-07' },
}, async ({
  customer: _loggedInCustomer,
  searchPage,
  basketPage,
  addressSelectPage,
  deliveryMethodPage,
  paymentPage,
  orderSummaryPage,
  orderCompletionPage,
  orderHistoryPage,
}) => {
  let orderId = '';

  await test.step('1. Add product A two times and product B one time from the product list', async () => {
    await searchPage.open();
    await searchPage.clickAddToBasket(PRODUCT_A_LINE.product);
    await searchPage.navbar.shouldSeeBasketCounter(1);
    await searchPage.clickAddToBasket(PRODUCT_A_LINE.product);
    await searchPage.navbar.shouldSeeBasketCounter(2);
    await searchPage.clickAddToBasket(PRODUCT_B_LINE.product);
    await searchPage.navbar.shouldSeeBasketCounter(3);
  });

  await test.step('2. Open the basket', async () => {
    await basketPage.open();
    await basketPage.shouldSeeLine(PRODUCT_A_LINE);
    await basketPage.shouldSeeLine(PRODUCT_B_LINE);
    await basketPage.shouldSeeTotalPrice(BASKET_TOTAL);
  });

  await test.step('3. Click Checkout, select the saved address and continue', async () => {
    await basketPage.clickCheckout();
    await addressSelectPage.selectAddress(SAVED_ADDRESS);
    await addressSelectPage.clickContinue();
    await deliveryMethodPage.shouldSeePage();
  });

  await test.step('4. Select One Day Delivery and continue', async () => {
    await deliveryMethodPage.selectDeliveryMethod(DELIVERY_METHODS.oneDay);
    await deliveryMethodPage.clickContinue();
    await paymentPage.shouldSeePage();
  });

  await test.step('5. Redeem the coupon of the current month', async () => {
    await paymentPage.openCouponPanel();
    await paymentPage.redeemCoupon(CouponHelper.currentMonthCode(COUPON_DISCOUNT_PERCENT));
    await paymentPage.shouldSeeCouponDiscountConfirmation(COUPON_DISCOUNT_PERCENT);
  });

  await test.step('6. Select the saved card and continue', async () => {
    await paymentPage.selectCard(SAVED_CARD);
    await paymentPage.clickContinue();
    await orderSummaryPage.shouldSeePage();
    await orderSummaryPage.shouldSeeDeliveryAddress(SAVED_ADDRESS);
    await orderSummaryPage.shouldSeeCardPayment(SAVED_CARD);
    await orderSummaryPage.shouldSeeTotals(EXPECTED_TOTALS);
  });

  await test.step('7. Click Place your order and pay', async () => {
    await orderSummaryPage.clickPlaceOrderAndPay();
    await orderCompletionPage.shouldSeeThankYou();
    orderId = await orderCompletionPage.readOrderId();
  });

  await test.step('8. Read the order summary on the confirmation page', async () => {
    await orderCompletionPage.shouldSeeProductLine(PRODUCT_A_LINE);
    await orderCompletionPage.shouldSeeProductLine(PRODUCT_B_LINE);
    await orderCompletionPage.shouldSeeTotals(EXPECTED_TOTALS);
  });

  await test.step('9. Read the basket counter and open the basket', async () => {
    await orderCompletionPage.navbar.shouldSeeBasketCounter(0);
    await basketPage.open();
    await basketPage.shouldSeeRowCount(0);
    await basketPage.shouldSeeCheckoutDisabled();
  });

  await test.step('10. Open the order history from the account menu', async () => {
    await basketPage.navbar.openOrderHistory();
    await orderHistoryPage.shouldSeePage();
    await orderHistoryPage.shouldSeeOrderCount(1);
    await orderHistoryPage.shouldSeeOrderId(0, orderId);
    await orderHistoryPage.shouldSeeOrderTotalPrice(0, EXPECTED_TOTALS.totalPrice);
    await orderHistoryPage.shouldSeeOrderProductLine(0, PRODUCT_A_LINE);
    await orderHistoryPage.shouldSeeOrderProductLine(0, PRODUCT_B_LINE);
  });
});

