import type { Locator, Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { expectText, expectUrl, expectVisible } from '@/utils/assertions/ui-assertions';
import { UI_ROUTE_PATTERNS, UI_ROUTES } from '@/utils/constants/routes';
import { UI_MESSAGES } from '@/utils/constants/ui-messages';
import type { Customer } from '@/utils/types/customer';

export class LoginPage extends BasePage {
  private readonly title: Locator;
  private readonly emailField: Locator;
  private readonly passwordField: Locator;
  private readonly logInButton: Locator;
  private readonly errorMessage: Locator;

  constructor(page: Page) {
    super(page);
    const root = page.locator('app-login');
    this.title = root.getByRole('heading', { level: 1 });
    this.emailField = root.getByRole('textbox', { name: 'Text field for the login email' });
    this.passwordField = root.getByRole('textbox', { name: 'Text field for the login password' });
    this.logInButton = root.locator('#loginButton');
    this.errorMessage = root.getByRole('alert');
  }

  /**
   * Puts the session of an API login into the browser, the same way the app keeps it after a UI login
   * (localStorage `token`, cookie `token`, sessionStorage `bid`), then opens the app.
   */
  async authenticate(customer: Customer): Promise<void> {
    await this.page.addInitScript(
      ({ token, basketId }) => {
        localStorage.setItem('token', token);
        sessionStorage.setItem('bid', String(basketId));
        document.cookie = `token=${token}; path=/`;
      },
      { token: customer.token, basketId: customer.basketId },
    );
    await this.page.goto(UI_ROUTES.home);
    await expectUrl(this.page, UI_ROUTE_PATTERNS.search, 'Product list after authentication');
  }

  async open(): Promise<void> {
    await this.page.goto(UI_ROUTES.login);
  }

  /** A real UI login. Use it only when the login screen is under test. */
  async login(email: string, password: string): Promise<void> {
    await this.emailField.fill(email);
    await this.passwordField.fill(password);
    await this.logInButton.click();
  }

  async shouldSeePage(): Promise<void> {
    await expectUrl(this.page, UI_ROUTE_PATTERNS.login, 'Login page');
    await expectText(this.title, 'Login', 'Login page title');
    await expectVisible(this.emailField, 'Field Email');
    await expectVisible(this.passwordField, 'Field Password');
    await expectText(this.logInButton, /Log in/, 'Button Log in');
  }

  async shouldSeeInvalidCredentialsError(): Promise<void> {
    await expectText(this.errorMessage, UI_MESSAGES.invalidLogin, 'Login error');
  }
}

/** API paths from docs/references/endpoints.csv. */
export const API_ROUTES = {
  users: '/api/Users',
  login: '/rest/user/login',
  productSearch: '/rest/products/search',
  basketItems: '/api/BasketItems',
  addresses: '/api/Addresss',
  cards: '/api/Cards',
  walletBalance: '/rest/wallet/balance',
} as const;

export const API_ROUTE_PATTERNS = {
  basketCoupon: /\/rest\/basket\/\d+\/coupon\//,
} as const;

/** Hash routes of the shop UI. */
export const UI_ROUTES = {
  home: '/',
  login: '/#/login',
  search: '/#/search',
  basket: '/#/basket',
  wallet: '/#/wallet',
} as const;

export const UI_ROUTE_PATTERNS = {
  login: /#\/login$/,
  search: /#\/search/,
  basket: /#\/basket$/,
  addressSelect: /#\/address\/select$/,
  deliveryMethod: /#\/delivery-method$/,
  payment: /#\/payment\/shop$/,
  orderSummary: /#\/order-summary$/,
  orderCompletion: /#\/order-completion\/([\w-]+)$/,
  orderHistory: /#\/order-history$/,
  wallet: /#\/wallet$/,
} as const;

import type { Locator, Page } from '@playwright/test';
import { BasePage } from '@/page-objects/base-page';
import { expectCount, expectText, expectUrl, expectVisible } from '@/utils/assertions/ui-assertions';
import { UI_ROUTE_PATTERNS } from '@/utils/constants/routes';
import { UI_MESSAGES } from '@/utils/constants/ui-messages';
import type { BasketLine } from '@/utils/types/shop';

/** The page `Order History`. Each order is a block with a heading row and a product table. */
export class OrderHistoryPage extends BasePage {
  private readonly root: Locator;
  private readonly orders: Locator;

  constructor(page: Page) {
    super(page);
    this.root = page.locator('app-order-history');
    this.orders = this.root.locator('.table-container');
  }

  async shouldSeePage(): Promise<void> {
    await expectUrl(this.page, UI_ROUTE_PATTERNS.orderHistory, 'Order history page');
    await expectVisible(this.root.getByText('Order History', { exact: true }), 'Order History title');
  }

  async shouldSeeNoOrders(): Promise<void> {
    await expectText(this.root.locator('.noResultText'), UI_MESSAGES.noOrdersYet, 'Empty order history');
    await expectCount(this.orders, 0, 'Orders');
  }

  async shouldSeeOrderCount(count: number): Promise<void> {
    await expectCount(this.orders, count, 'Orders');
  }

  async shouldSeeOrderId(orderIndex: number, orderId: string): Promise<void> {
    await expectText(this.headingValue(orderIndex, 'Order ID'), `#${orderId}`, 'Order ID');
  }

  async shouldSeeOrderTotalPrice(orderIndex: number, totalPrice: string): Promise<void> {
    await expectText(this.headingValue(orderIndex, 'Total Price'), totalPrice, 'Order Total Price');
  }

  async shouldSeeOrderBonus(orderIndex: number, bonus: number): Promise<void> {
    await expectText(this.headingValue(orderIndex, 'Bonus'), String(bonus), 'Order Bonus');
  }

  async shouldSeeOrderProductLine(orderIndex: number, line: BasketLine): Promise<void> {
    const row = this.orders
      .nth(orderIndex)
      .locator('mat-row')
      .filter({ has: this.page.locator('mat-cell.mat-column-product', { hasText: line.product.name }) });
    await expectCount(row, 1, `Order line of ${line.product.name}`);
    await expectText(row.locator('mat-cell.mat-column-quantity'), String(line.quantity), `Quantity of ${line.product.name}`);
  }

  private headingValue(orderIndex: number, label: string): Locator {
    return this.orders
      .nth(orderIndex)
      .locator('.col-vertical')
      .filter({ has: this.page.getByText(label, { exact: true }) })
      .locator('div')
      .last();
  }
}

import { createCustomer } from '@/core/api/customer-setup';
import { test } from '@/fixtures/pages.fixture';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import { ACCOUNT_MENU_ITEMS } from '@/utils/constants/ui-messages';

test('Login with a wrong password, then with the correct password', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.auth],
  annotation: { type: 'test-case', description: 'TC-01' },
}, async ({ api, loginPage, searchPage }) => {
  const customer = await test.step('Precondition: create a new customer account', () => createCustomer(api));
  const wrongPassword = `${customer.password}x`;

  await test.step('1. Open the login page', async () => {
    await loginPage.open();
    await loginPage.shouldSeePage();
  });

  await test.step('2. Log in with the email and the wrong password', async () => {
    await loginPage.login(customer.email, wrongPassword);
    await loginPage.shouldSeeInvalidCredentialsError();
    await loginPage.shouldSeePage();
  });

  await test.step('3. Open the account menu', async () => {
    await loginPage.navbar.openAccountMenu();
    await loginPage.navbar.shouldSeeAccountMenuItem(ACCOUNT_MENU_ITEMS.login);
    await loginPage.navbar.shouldNotSeeInAccountMenu(customer.email);
  });

  await test.step('4. Close the menu and log in with the correct password', async () => {
    await loginPage.navbar.closeAccountMenu();
    await loginPage.login(customer.email, customer.password);
    await searchPage.shouldSeePage();
  });

  await test.step('5. Open the account menu', async () => {
    await searchPage.navbar.openAccountMenu();
    await searchPage.navbar.shouldSeeEmailInAccountMenu(customer.email);
    await searchPage.navbar.shouldSeeAccountMenuItem(ACCOUNT_MENU_ITEMS.logout);
  });
});

