import { test } from '@/fixtures/customer.fixture';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import { PRODUCTS } from '@/utils/constants/shop-data';

const PRODUCT_A = PRODUCTS.raspberryJuice;
const PRODUCT_B = PRODUCTS.eggfruitJuice;

const TOTAL = {
  oneOfEach: '13.98¤',
  twoOfProductA: '18.97¤',
  onlyProductB: '8.99¤',
};

test.use({
  customerSetup: {
    basket: [
      { product: PRODUCT_A, quantity: 1 },
      { product: PRODUCT_B, quantity: 1 },
    ],
  },
});

test('Change the quantity and remove a product in the basket', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.cart],
  annotation: { type: 'test-case', description: 'TC-03' },
}, async ({ customer: _loggedInCustomer, basketPage }) => {
  await test.step('1. Open the basket', async () => {
    await basketPage.open();
    await basketPage.shouldSeeRowCount(2);
    await basketPage.shouldSeeLine({ product: PRODUCT_A, quantity: 1 });
    await basketPage.shouldSeeLine({ product: PRODUCT_B, quantity: 1 });
    await basketPage.shouldSeeTotalPrice(TOTAL.oneOfEach);
    await basketPage.navbar.shouldSeeBasketCounter(2);
  });

  await test.step('2. Click the plus button in the row of product A', async () => {
    await basketPage.clickIncreaseQuantity(PRODUCT_A);
    await basketPage.shouldSeeQuantity(PRODUCT_A, 2);
    await basketPage.shouldSeeTotalPrice(TOTAL.twoOfProductA);
    await basketPage.navbar.shouldSeeBasketCounter(3);
  });

  await test.step('3. Click the minus button in the row of product A', async () => {
    await basketPage.clickDecreaseQuantity(PRODUCT_A);
    await basketPage.shouldSeeQuantity(PRODUCT_A, 1);
    await basketPage.shouldSeeTotalPrice(TOTAL.oneOfEach);
    await basketPage.navbar.shouldSeeBasketCounter(2);
  });

  await test.step('4. Click the minus button in the row of product A again', async () => {
    await basketPage.clickDecreaseQuantity(PRODUCT_A);
    await basketPage.shouldKeepQuantity(PRODUCT_A, 1);
    await basketPage.shouldSeeLine({ product: PRODUCT_A, quantity: 1 });
    await basketPage.shouldKeepTotalPrice(TOTAL.oneOfEach);
  });

  await test.step('5. Click the trash button in the row of product A', async () => {
    await basketPage.clickRemove(PRODUCT_A);
    await basketPage.shouldNotSeeProduct(PRODUCT_A);
    await basketPage.shouldSeeLine({ product: PRODUCT_B, quantity: 1 });
    await basketPage.shouldSeeTotalPrice(TOTAL.onlyProductB);
    await basketPage.navbar.shouldSeeBasketCounter(1);
  });
});

