1	import { encode } from 'z85';
2	
3	const MONTHS = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'] as const;
4	const TWO_DIGITS = 2;
5	const CENTURY = 100;
6	
7	/**
8	 * Coupon codes of test-cases/README.md: the Z85 encoding of `<MMM><YY>-<NN>`.
9	 * The server checks the month in its local time, and the tests run on the same machine,
10	 * so the month comes from the local time of this machine.
11	 */
12	export class CouponHelper {
13	  static currentMonthCode(discountPercent: number, now: Date = new Date()): string {
14	    return CouponHelper.codeFor(now, discountPercent);
15	  }
16	
17	  static previousMonthCode(discountPercent: number, now: Date = new Date()): string {
18	    const previousMonth = new Date(now.getFullYear(), now.getMonth() - 1, 1);
19	    return CouponHelper.codeFor(previousMonth, discountPercent);
20	  }
21	
22	  private static codeFor(month: Date, discountPercent: number): string {
23	    const year = String(month.getFullYear() % CENTURY).padStart(TWO_DIGITS, '0');
24	    const discount = String(discountPercent).padStart(TWO_DIGITS, '0');
25	    const code = encode(`${MONTHS[month.getMonth()]}${year}-${discount}`);
26	    if (!code) throw new Error(`Cannot encode the coupon text for ${month.toDateString()}`);
27	    return code;
28	  }
29	}
