1	/**
2	 * Test-data setup for a customer through the API: a new account, a basket, the saved address
3	 * and card of test-cases/README.md, and money in the wallet.
4	 */
5	import { randomUUID } from 'node:crypto';
6	import type { JuiceShopApi } from '@/core/api/juice-shop-api';
7	import { SAVED_ADDRESS, SAVED_CARD } from '@/utils/constants/shop-data';
8	import type { Customer } from '@/utils/types/customer';
9	import type { BasketLine } from '@/utils/types/shop';
10	
11	const EMAIL_DOMAIN = 'example.test';
12	const UNIQUE_PART_LENGTH = 8;
13	
14	export interface CustomerSetup {
15	  basket?: BasketLine[];
16	  withSavedAddressAndCard?: boolean;
17	  /** Money to add to the wallet. Needs the saved card. */
18	  walletBalance?: number;
19	}
20	
21	/** Registers a new normal customer with a unique email and logs it in through the API. */
22	export async function createCustomer(api: JuiceShopApi): Promise<Customer> {
23	  const unique = `${Date.now()}-${randomUUID().slice(0, UNIQUE_PART_LENGTH)}`;
24	  const credentials = { email: `customer-${unique}@${EMAIL_DOMAIN}`, password: `Pw-${unique}!` };
25	  await api.users.register(credentials);
26	  return api.users.login(credentials);
27	}
28	
29	export async function fillBasket(api: JuiceShopApi, customer: Customer, lines: BasketLine[]): Promise<void> {
30	  for (const line of lines) {
31	    const productId = await api.products.findIdByName(line.product.name);
32	    await api.basket.addItem(customer, productId, line.quantity);
33	  }
34	}
35	
36	/** Saves the address and the card of test-cases/README.md. Returns the customer with the card id. */
37	export async function addSavedAddressAndCard(api: JuiceShopApi, customer: Customer): Promise<Customer> {
38	  await api.paymentData.addAddress(customer, SAVED_ADDRESS);
39	  const savedCardId = await api.paymentData.addCard(customer, SAVED_CARD);
40	  return { ...customer, savedCardId };
41	}
42	
43	/** Adds money to the wallet with the saved card of the customer. */
44	export async function addWalletMoney(api: JuiceShopApi, customer: Customer, amount: number): Promise<void> {
45	  if (customer.savedCardId === undefined) {
46	    throw new Error('The wallet top-up needs a saved card. Save the card first.');
47	  }
48	  await api.paymentData.addWalletMoney(customer, amount, customer.savedCardId);
49	}
50	
51	/** Creates a new customer and prepares the data that the setup asks for. */
52	export async function createPreparedCustomer(api: JuiceShopApi, setup: CustomerSetup): Promise<Customer> {
53	  let customer = await createCustomer(api);
54	  if (setup.withSavedAddressAndCard) customer = await addSavedAddressAndCard(api, customer);
55	  if (setup.basket?.length) await fillBasket(api, customer, setup.basket);
56	  if (setup.walletBalance) await addWalletMoney(api, customer, setup.walletBalance);
57	  return customer;
58	}
