/** Checks that an element does not appear during a fixed time window. */
export async function expectAbsentHolds(locator: Locator, description: string): Promise<void> {
  let maxCount = 0;
  const deadline = Date.now() + ABSENCE_HOLD_MS;
  await expect
    .poll(
      async () => {
        maxCount = Math.max(maxCount, await locator.count());
        return Date.now() >= deadline;
      },
      { intervals: [HOLD_POLL_INTERVAL_MS], timeout: ABSENCE_HOLD_MS + DateHelper.secondsToMs(5) },
    )
    .toBe(true);
  expect(maxCount, `${description} does not appear`).toBe(0);
}

