import { expect, type Locator, type Page } from '@playwright/test';
import { expectHidden, expectVisible } from '@/utils/assertions/ui-assertions';
import { DateHelper } from '@/utils/helpers/date-helper';

const MESSAGE_CLOSE_TIMEOUT_MS = DateHelper.secondsToMs(15);

/** The short messages at the bottom of the page (Angular Material snack bar). */
export class SnackBarComponent {
  private readonly confirmations: Locator;
  private readonly errors: Locator;

  constructor(page: Page) {
    this.confirmations = page.locator('.mat-mdc-snack-bar-container.confirmBar');
    this.errors = page.locator('.mat-mdc-snack-bar-container.errorBar');
  }

  async shouldSeeMessage(text: string): Promise<void> {
    await expectVisible(this.confirmations.filter({ hasText: text }), `Message "${text}"`);
  }

  async shouldSeeErrorMessage(text: string): Promise<void> {
    await expectVisible(this.errors.filter({ hasText: text }), `Error message "${text}"`);
  }

  async shouldNotSeeErrorMessage(): Promise<void> {
    await expectHidden(this.errors, 'Error message');
  }

  /** Waits until earlier messages close by themselves, so that the next check sees only a new message. */
  async waitForMessagesToClose(): Promise<void> {
    await expect(this.confirmations.or(this.errors), 'Earlier messages close').toHaveCount(0, {
      timeout: MESSAGE_CLOSE_TIMEOUT_MS,
    });
  }
}

