import { addWalletMoney } from '@/core/api/customer-setup';
import { test } from '@/fixtures/customer.fixture';
import { checkoutWithSavedAddress } from '@/tests/helpers/checkout-flows';
import { AUTOTEST_PLAYWRIGHT_TAGS } from '@/utils/constants/autotest-labels';
import { DELIVERY_METHODS, PRODUCTS, SAVED_ADDRESS } from '@/utils/constants/shop-data';
import { UI_MESSAGES } from '@/utils/constants/ui-messages';

const ORDER_TOTAL = '8.99¤';
const PAY_BUTTON_AMOUNT = ORDER_TOTAL;
const FIRST_WALLET_BALANCE = 5;
const TOP_UP_FOR_PART_2 = 3.99;
const ORDER_BONUS_POINTS = 1;

const SHOWN_BALANCE = {
  first: '5.00',
  equalToOrderTotal: '8.99',
  afterOrderWithBonus: '1.00',
};

test.use({
  customerSetup: {
    withSavedAddressAndCard: true,
    basket: [{ product: PRODUCTS.eggfruitJuice, quantity: 1 }],
    walletBalance: FIRST_WALLET_BALANCE,
  },
});

test('Pay an order with the wallet: too little money, then exactly the order total', {
  tag: [AUTOTEST_PLAYWRIGHT_TAGS.wallet],
  annotation: { type: 'test-case', description: 'TC-08' },
}, async ({
  api,
  customer,
  basketPage,
  addressSelectPage,
  deliveryMethodPage,
  paymentPage,
  orderSummaryPage,
  orderCompletionPage,
  orderHistoryPage,
  walletPage,
}) => {
  await test.step('1. Open the basket, click Checkout, select the saved address and continue', async () => {
    await checkoutWithSavedAddress({ basketPage, addressSelectPage }, SAVED_ADDRESS);
    await deliveryMethodPage.shouldSeePage();
  });

  await test.step('2. Select Standard Delivery and continue', async () => {
    await deliveryMethodPage.selectDeliveryMethod(DELIVERY_METHODS.standard);
    await deliveryMethodPage.clickContinue();
    await paymentPage.shouldSeePage();
    await paymentPage.shouldSeeWalletBalance(SHOWN_BALANCE.first);
  });

  await test.step('3. Read the wallet pay button', async () => {
    await paymentPage.shouldSeeWalletPayButtonDisabled(PAY_BUTTON_AMOUNT);
  });

  await test.step('4. Open the order history from the account menu', async () => {
    await paymentPage.navbar.openOrderHistory();
    await orderHistoryPage.shouldSeePage();
    await orderHistoryPage.shouldSeeNoOrders();
  });

  await test.step('5. Open the digital wallet from the account menu', async () => {
    await orderHistoryPage.navbar.openDigitalWallet();
    await walletPage.shouldSeePage();
    await walletPage.shouldSeeBalance(SHOWN_BALANCE.first);
  });

  await test.step('Precondition: add money to the wallet so that it holds the order total', async () => {
    await addWalletMoney(api, customer, TOP_UP_FOR_PART_2);
  });

  await test.step('6. Go to the payment step again with Standard Delivery', async () => {
    await checkoutWithSavedAddress({ basketPage, addressSelectPage }, SAVED_ADDRESS);
    await deliveryMethodPage.selectDeliveryMethod(DELIVERY_METHODS.standard);
    await deliveryMethodPage.clickContinue();
    await paymentPage.shouldSeePage();
    await paymentPage.shouldSeeWalletBalance(SHOWN_BALANCE.equalToOrderTotal);
    await paymentPage.shouldSeeWalletPayButtonEnabled(PAY_BUTTON_AMOUNT);
  });

  await test.step('7. Click the wallet pay button', async () => {
    await paymentPage.clickPayWithWallet(PAY_BUTTON_AMOUNT);
    await orderSummaryPage.shouldSeePage();
    await orderSummaryPage.shouldSeePaymentMethod(UI_MESSAGES.digitalWalletPayment);
    await orderSummaryPage.shouldSeeTotalPrice(ORDER_TOTAL);
  });

  await test.step('8. Click Place your order and pay', async () => {
    await orderSummaryPage.clickPlaceOrderAndPay();
    await orderCompletionPage.shouldSeePage();
    await orderCompletionPage.shouldSeeThankYou();
  });

  await test.step('9. Open the digital wallet from the account menu', async () => {
    await orderCompletionPage.navbar.openDigitalWallet();
    await walletPage.shouldSeePage();
    await walletPage.shouldSeeBalance(SHOWN_BALANCE.afterOrderWithBonus);
  });

  await test.step('10. Open the order history from the account menu', async () => {
    await walletPage.navbar.openOrderHistory();
    await orderHistoryPage.shouldSeePage();
    await orderHistoryPage.shouldSeeOrderCount(1);
    await orderHistoryPage.shouldSeeOrderTotalPrice(0, ORDER_TOTAL);
    await orderHistoryPage.shouldSeeOrderBonus(0, ORDER_BONUS_POINTS);
  });
});

