1	import { expect, type Locator, type Page } from '@playwright/test';
2	import { DateHelper } from '@/utils/helpers/date-helper';
3	
4	/** How long an "it does not change" check keeps reading the value. */
5	export const ABSENCE_HOLD_MS = DateHelper.secondsToMs(2);
6	const HOLD_POLL_INTERVAL_MS = 250;
7	
8	export async function expectVisible(locator: Locator, description: string): Promise<void> {
9	  await expect(locator, `${description} is visible`).toBeVisible();
10	}
11	
12	export async function expectHidden(locator: Locator, description: string): Promise<void> {
13	  await expect(locator, `${description} is not visible`).toBeHidden();
14	}
15	
16	export async function expectText(locator: Locator, text: string | RegExp | string[], description: string): Promise<void> {
17	  await expect(locator, `${description} has the text ${String(text)}`).toHaveText(text);
18	}
19	
20	export async function expectContainText(locator: Locator, text: string | RegExp, description: string): Promise<void> {
21	  await expect(locator, `${description} contains ${String(text)}`).toContainText(text);
22	}
23	
24	export async function expectCount(locator: Locator, count: number, description: string): Promise<void> {
25	  await expect(locator, `${description}: count is ${count}`).toHaveCount(count);
26	}
27	
28	export async function expectEnabled(locator: Locator, description: string): Promise<void> {
29	  await expect(locator, `${description} is enabled`).toBeEnabled();
30	}
31	
32	export async function expectDisabled(locator: Locator, description: string): Promise<void> {
33	  await expect(locator, `${description} is disabled`).toBeDisabled();
34	}
35	
36	export async function expectUrl(page: Page, url: RegExp, description: string): Promise<void> {
37	  await expect(page, `${description}: URL matches ${String(url)}`).toHaveURL(url);
38	}
39	
40	/**
41	 * Checks that a text stays the same for a fixed time window.
42	 * A retrying assertion passes at the first match, so it cannot show that a value does not change later.
43	 */
44	export async function expectTextHolds(locator: Locator, text: string, description: string): Promise<void> {
45	  await expectText(locator, text, description);
46	  const seen = new Set<string>();
47	  const deadline = Date.now() + ABSENCE_HOLD_MS;
48	  await expect
49	    .poll(
50	      async () => {
51	        seen.add((await locator.innerText()).trim());
52	        return Date.now() >= deadline;
53	      },
54	      { intervals: [HOLD_POLL_INTERVAL_MS], timeout: ABSENCE_HOLD_MS + DateHelper.secondsToMs(5) },
55	    )
56	    .toBe(true);
57	  expect([...seen], `${description} keeps the text ${text}`).toEqual([text]);
58	}
59	
60	/** Checks that an element does not appear during a fixed time window. */
61	export async function expectAbsentHolds(locator: Locator, description: string): Promise<void> {
62	  let maxCount = 0;
63	  const deadline = Date.now() + ABSENCE_HOLD_MS;
64	  await expect
65	    .poll(
66	      async () => {
67	        maxCount = Math.max(maxCount, await locator.count());
68	        return Date.now() >= deadline;
69	      },
70	      { intervals: [HOLD_POLL_INTERVAL_MS], timeout: ABSENCE_HOLD_MS + DateHelper.secondsToMs(5) },
71	    )
72	    .toBe(true);
73	  expect(maxCount, `${description} does not appear`).toBe(0);
74	}
